using System;
using System.Security.Claims;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using RAGGit.Core.Abstractions.Repositories;
using RAGGit.Core.Models;
using RAGGit.Documents;

namespace RAGGit.Workstation.Api.Controllers;

/// <summary>
/// 033: renders an owned grounded answer as a downloadable document. The
/// endpoint is a read-only projection of the persisted query: it never calls
/// the model and never retains the generated bytes.
/// </summary>
[ApiController]
[Route("api/queries")]
[Authorize]
public sealed class QueryDocumentsController : ControllerBase
{
    private readonly IQueryRepository _queries;
    private readonly DocumentGenerator _generator;
    private readonly ILogger<QueryDocumentsController> _logger;

    public QueryDocumentsController(
        IQueryRepository queries,
        DocumentGenerator generator,
        ILogger<QueryDocumentsController> logger
    )
    {
        _queries = queries ?? throw new ArgumentNullException(nameof(queries));
        _generator = generator ?? throw new ArgumentNullException(nameof(generator));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    /// <summary>
    /// POST /api/queries/{id}/documents — the owned answer as docx/xlsx/pdf/txt.
    /// 404 for not found/not owned/legacy; 422 for a refusal, a citationless
    /// answer or a too-large result; 400 for an unsupported format.
    /// </summary>
    [HttpPost("{id:guid}/documents")]
    [Authorize(Roles = "Employee,Admin")]
    public async Task<IActionResult> Render(
        Guid id,
        [FromBody] DocumentRequest? request,
        CancellationToken cancellationToken
    )
    {
        if (
            request is null
            || !DocumentOutputFormatExtensions.TryParse(request.Format, out var format)
        )
        {
            return BadRequest(new { error = "unsupported format" });
        }

        var sub = User.FindFirstValue(ClaimTypes.NameIdentifier) ?? User.FindFirst("sub")?.Value;
        if (string.IsNullOrWhiteSpace(sub))
        {
            return Unauthorized(new { error = "unauthorized" });
        }

        var detail = await _queries.GetDetailAsync(sub, id, cancellationToken);
        if (detail is null)
        {
            return NotFound(new { error = "not found" });
        }

        try
        {
            var document = _generator.Generate(detail, format);
            _logger.LogInformation(
                "Rendered {Format} document for query {QueryId}: {Bytes} bytes",
                format,
                id,
                document.ByteCount
            );

            return File(document.Bytes, document.ContentType, document.FileName);
        }
        catch (DocumentGenerationException exception)
        {
            _logger.LogInformation(
                "Document request for query {QueryId} rejected: {Error}",
                id,
                exception.Error
            );

            return exception.Error == DocumentGenerationError.UnsupportedFormat
                ? BadRequest(new { error = "unsupported format" })
                : StatusCode(
                    StatusCodes.Status422UnprocessableEntity,
                    new { error = exception.Message }
                );
        }
        catch (Exception exception)
        {
            // Never expose renderer internals or answer content in the response.
            _logger.LogError(exception, "Document rendering failed for query {QueryId}", id);
            return StatusCode(
                StatusCodes.Status500InternalServerError,
                new { error = "document generation failed" }
            );
        }
    }
}
